            // Reference model
            ext_a = {test_a[7], test_a};
            ext_b = {test_b[7], test_b};
            ext_s = ext_a + ext_b;

            expected_sum = ext_s[7:0];
            // Signed overflow happens if result exceeds [-128, 127]
            expected_overflow = (ext_s > 9'sd127) || (ext_s < -9'sd128);

            // Use case inequality (`!==`) as mandated by contract
